#!/usr/bin/env python3
"""Build the self-contained DISC copy: index.html."""
import json

# ---- data ----
with open("questions.json", encoding="utf-8") as f:
    q = json.load(f)          # 24 lists, each 4 items [{type, text}]
assert len(q) == 24

TABS = ["Первый", "Второй", "Третий", "Четвёртый", "Пятый", "Шестой", "Седьмой", "Восьмой"]

HANDLE = (
    '<span class="disc-handle" aria-hidden="true">'
    '<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16" fill="#B3B3B3">'
    '<circle cx="5" cy="4" r="1"/><circle cx="9" cy="4" r="1"/>'
    '<circle cx="5" cy="8" r="1"/><circle cx="9" cy="8" r="1"/>'
    '<circle cx="5" cy="12" r="1"/><circle cx="9" cy="12" r="1"/>'
    '</svg></span>'
)

def esc(s):
    return (s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"))

def make_list(li_idx):
    items = q[li_idx]
    lis = []
    for it in items:
        lis.append(
            f'              <li class="disc-item" data-type="{it["type"]}">'
            f'{esc(it["text"])}{HANDLE}</li>'
        )
    body = "\n".join(lis)
    return (
        f'          <div class="disc-card">\n'
        f'            <div class="disc-card__title">Я наиболее</div>\n'
        f'            <ul class="disc-list" id="draggable-list{li_idx + 1}">\n'
        f'{body}\n'
        f'            </ul>\n'
        f'            <div class="disc-card__foot">Я наименее</div>\n'
        f'          </div>'
    )

def make_pane(p_idx):
    cards = [make_list(p_idx * 3 + j) for j in range(3)]
    grid = "\n".join(cards)
    return (
        f'        <div class="disc-pane is-active" data-pane="{p_idx}">\n'
        f'          <div class="disc-grid3">\n'
        f'{grid}\n'
        f'          </div>\n'
        f'        </div>'
    )

tabs_html = "\n".join(
    f'        <button class="disc-tab{" is-active" if i == 0 else ""}" role="tab" data-step="{i}" aria-label="{TABS[i]}">{TABS[i]}</button>'
    for i in range(8)
)

panes_html = "\n".join(make_pane(i) for i in range(8))

