const { WebSocket } = require('ws');
const { spawn } = require('child_process');
const http = require('http');

const PORT = 9231;
const pageFile = process.cwd() + '/index.html';
const chrome = spawn('google-chrome', [
  '--headless=new', '--no-sandbox', '--disable-gpu',
  '--remote-debugging-port=' + PORT, '--window-size=1400,900',
  '--allow-file-access-from-files', pageFile
], { stdio: 'ignore' });

function getJson() {
  return new Promise((res, rej) => {
    http.get('http://127.0.0.1:' + PORT + '/json', (r) => {
      let d = ''; r.on('data', c => d += c); r.on('end', () => res(JSON.parse(d)));
    }).on('error', rej);
  });
}
function pollJson() {
  return new Promise((res, rej) => {
    let t = 0;
    (function tick() {
      getJson().then((targets) => {
        const page = targets.find(x => x.type === 'page' && x.url && x.url.includes('index.html'));
        if (page) return res(page);
        t++;
        if (t > 40) return rej(new Error('no page'));
        setTimeout(tick, 400);
      }).catch(() => { t++; if (t > 40) return rej(new Error('poll fail')); setTimeout(tick, 400); });
    })();
  });
}

let ws;
function call(method, params) {
  return new Promise((res, rej) => {
    const id = Math.random().toString(36).slice(2);
    const h = ws.on('message', (m) => {
      try {
        const r = JSON.parse(m.toString());
        if (r && r.id === id) { ws.removeListener('message', h); res(r); }
      } catch (e) {}
    });
    ws.send(JSON.stringify({ id, method, params: params || {} }));
    setTimeout(() => { ws.removeListener('message', h); rej(new Error('timeout ' + method)); }, 5000);
  });
}

pollJson().then((page) => {
  ws = new WebSocket(page.webSocketDebuggerUrl);
  ws.on('open', async () => {
    await call('Page.enable', {});
    await call('DOM.enable', {});
    await call('Runtime.enable', {});
    await call('Page.navigate', { url: pageFile });
    // wait for load
    await new Promise(res => { ws.on('message', (m) => { try { const r = JSON.parse(m.toString()); if (r && r.event && r.event.type === 'pageLoadEventFired') res(true); } catch (e) {} }); setTimeout(res, 5000); });
    console.log('loaded, waiting 1000ms...');
    await new Promise(r => setTimeout(r, 1000));
    const r = await call('Runtime.evaluate', {
      expression: `(()=>{const ul=document.querySelector('#draggable-list1');if(!ul)return{ul:null,len:-1};return{ul:ul.tagName,len:Array.from(ul.children).length,first:Array.from(ul.children).map(e=>e.dataset.type)};})()`,
      returnByValue: true
    });
    console.log('evaluate result:', JSON.stringify(r.result));
    // also test a trivial one
    const r2 = await call('Runtime.evaluate', { expression: 'document.title', returnByValue: true });
    console.log('title:', JSON.stringify(r2.result));
    chrome.kill();
    process.exit(0);
  });
  ws.on('error', e => { console.log('ws error', e.message); chrome.kill(); process.exit(1); });
  ws.on('close', () => { console.log('ws closed'); chrome.kill(); process.exit(2); });
}).catch((e) => { console.log('poll fail', e.message); chrome.kill(); process.exit(3); });

const { WebSocket } = require('ws');
const { spawn } = require('child_process');
const http = require('http');

const PORT = 9232;
const pageFile = process.cwd() + '/index.html';
const chrome = spawn('google-chrome', [
  '--headless=new', '--no-sandbox', '--disable-gpu',
  '--remote-debugging-port=' + PORT, '--window-size=1400,900',
  '--allow-file-access-from-files', pageFile
], { stdio: 'ignore' });

function getJson() {
  return new Promise((res, rej) => {
    http.get('http://127.0.0.1:' + PORT + '/json', (r) => {
      let d = ''; r.on('data', c => d += c); r.on('end', () => res(JSON.parse(d)));
    }).on('error', rej);
  });
}
function pollJson() {
  return new Promise((res, rej) => {
    let t = 0;
    (function tick() {
      getJson().then((targets) => {
        const page = targets.find(x => x.type === 'page' && x.url && x.url.includes('index.html'));
        if (page) return res(page);
