'use strict';
const http = require('http');
const { WebSocket } = require('ws');
const PORT = 9229, URL = 'file://' + __dirname + '/index.html';

function getJSON(url){
  return new Promise((resolve,reject)=>{
    http.get(url, (r)=>{let b='';r.on('data',d=>b+=d);r.on('end',()=>resolve(JSON.parse(b)));});
  }).catch(reject);
}
function sleep(ms){ return new Promise(r=>setTimeout(r,ms)); }
function evalVal(r){
  const rr = (r && r.result) ? r.result : {};
  const inner = (rr && rr.result) ? rr.result : rr;
  return inner && inner.value;
}

function main(){
  const wsUrl = process.argv[2] || null;
  let ws, nextId = 1;
  function call(method, params){
    return new Promise((res,reject)=>{
      const id = nextId++;
      const h = function onmsg(m){
        try{
          const raw = Buffer.isBuffer(m) ? m.toString('utf8') : (typeof m === 'string' ? m : JSON.stringify(m));
          const r = JSON.parse(raw);
          if (r && r.id === id){ res(r); ws.removeEventListener('message', h); }
        }catch(e){}
      };
      ws.on('message', h);
      ws.send(JSON.stringify({ id:id, method, params: params||{} }));
    });
  }

  let done = () => { process.exit(0); };
  const fail = (msg) => { console.log('FAIL ' + msg); kill(); done(); };
  function kill(){ try{ if(ws) ws.close(); }catch(e){} process.exit(0); }

  const openPage = () => {
    const proc = require('child_process').spawn('google-chrome', [
      '--headless=new','--disable-gpu','--window-size=1280,900',
      '--remote-debugging-port='+PORT,
      '--no-sandbox','--disable-dev-shm-usage','--allow-file-access-from-files','--no-first-run','--lang=ru',
      '--start-maximized', URL
    ], { stdio: ['ignore','ignore','inherit'] });
    proc.on('exit', (code) => {});
    return proc;
  };

  // 1. launch chrome
  console.log('[0] launching chrome...');
  const proc = openPage();
  return new Promise((resolve)=>{
    let n = 0;
    (function poll(){
      n += 1;
      http.get('http://127.0.0.1:' + PORT + '/json', (r)=>{
        r.on('data', d => {
          r.on('end', () => {
            try{
              const targets = JSON.parse(d.toString());
              const page = targets.find(t => t.type === 'page');
              if(page){ console.log('[1] wsUrl: ' + page.webSocketDebuggerUrl); resolve(page.webSocketDebuggerUrl); }
              else { if(n < 15) setTimeout(poll, 400); else { console.log('no page'); kill(); } }
            }catch(e){ if(n < 15) setTimeout(poll, 400); else kill(); }
          });
        });
      }).catch(()=>{ if(n < 15) setTimeout(poll, 400); else kill(); });
    })();
  }).then(wsUrl => {
    return new Promise((resolve, reject) => {
      ws = new WebSocket(wsUrl);
      ws.on('open', () => {
        console.log('[0] ws open');
        resolve();
      });
      ws.on('error', reject);
    });
  }).then(() => {
    return call('Page.enable').then(()=>{
      return call('DOM.enable').then(()=>{
        return call('Runtime.enable').then(()=>{
          return new Promise((resolve) => {
            let n = 0;
            (function poll(){
              n += 1;
              const expr = `(() => { const ul = document.querySelector('#draggable-list1'); return ul ? 1 : 0; })()`;
              call('Runtime.evaluate', { expression: expr, returnByValue: true }).then(r => {
                if (evalVal(r) === 1) { console.log('[1] ready, list1 found'); resolve(); }
                else if (n < 40) setTimeout(poll, 300);
                else { console.log('timeout'); kill(); }
              }).catch(() => { if (n < 40) setTimeout(poll, 300); else kill(); });
            })();
          });
        });
      });
    });
  }).then(() => {
    // helper: read item geometry
    return call('Runtime.evaluate', {
      expression: `(() => { const ul = document.querySelector('#draggable-list1'); if (!ul) return null; return Array.from(ul.children).map((el, i) => { const r = el.getBoundingClientRect(); return { i, x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2), type: el.dataset.type, text: el.textContent.replace(/<[^>]*>/g, '').trim() }; }); })()`,
      returnByValue: true
    }).then(r => {
      const items = evalVal(r);
      if (!items || !items.length) { fail('no items'); return; }
      console.log('[2] list1:', JSON.stringify(items.map(i => i.i + ':' + i.text)));
      return items;
    });
  }).then(items => {
    // open modal
    return call('Runtime.evaluate', { expression: 'document.getElementById("btnStart").click()', returnByValue: true });
  }).then(() => sleep(300)).then(() => {
    return call('Runtime.evaluate', { expression: 'document.getElementById("wizardmodal").classList.contains("is-open")', returnByValue: true }).then(r => {
      if (evalVal(r) !== true) { fail('modal not open'); return; }
      console.log('[3] modal open');
      return call('Runtime.evaluate', { expression: '!!window.__discDrag.state()', returnByValue: true }).then(r => console.log('[3.1] pre-drag state=' + evalVal(r)));
    });
  }).then(() => {
    return call('Runtime.evaluate', {
      expression: `(() => { const ul = document.querySelector('#draggable-list1'); const it = Array.from(ul.children)[2]; const r = it.getBoundingClientRect(); return { x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2), top: Math.round(r.top), bottom: Math.round(r.bottom) }; })()`,
      returnByValue: true
    }).then(r => {
      const pos = evalVal(r);
      console.log('[4] item2 geometry:', JSON.stringify(pos));
      return pos;
    });
  }).then((startPos) => {
    const startX = startPos.x, startY = startPos.y;
    console.log('[5] dispatch pointerdown at (' + startX + ',' + startY + ')');
    return call('Input.dispatchPointerEvent', { eventType: 'pointerdown', x: startX, y: startY, button: 'Left', pressed: true, pointerType: 'mouse', pointerId: 1 });
  }).then(() => sleep(100)).then(() => {
    return call('Runtime.evaluate', { expression: '!!window.__discDrag.state()', returnByValue: true }).then(r => {
      const active = evalVal(r);
      console.log('[6] after pointerdown: drag ACTIVE=' + active);
      return active;
    });
  }).then(active => {
    if (!active) { fail('drag not started after pointerdown!'); return; }
    // pointermove up by half
    const y1 = Math.round(startY - 40), y2 = Math.round(startY - 70);
    console.log('[7] pointermove to (' + startX + ',' + y1 + ')');
    return call('Input.dispatchPointerEvent', { eventType: 'pointermove', x: startX, y: y1, pressed: true, pointerType: 'mouse', pointerId: 1 });
  }).then(() => sleep(100)).then(() => {
    return Promise.all([
      call('Runtime.evaluate', { expression: '!!window.__discDrag.state()', returnByValue: true }).then(r => { const a = evalVal(r); console.log('[8] after move1: ACTIVE=' + a); return a; }),
      call('Runtime.evaluate', {
        expression: `(() => { const ul = document.querySelector('#draggable-list1'); return Array.from(ul.children).map((el) => el.textContent.replace(/<[^>]*>/g, '').trim()); })()`,
        returnByValue: true
      }).then(r => { console.log('[9] order after move1:', JSON.stringify(evalVal(r))); return evalVal(r); })
    ]);
  }).then(() => {
    console.log('[10] pointermove to item0 region');
    return call('Runtime.evaluate', {
      expression: `(() => { const ul = document.querySelector('#draggable-list1'); const it = Array.from(ul.children)[0]; const r = it.getBoundingClientRect(); return Math.round(r.top + r.height / 2); })()`,
      returnByValue: true
    }).then(r => {
      const item0Y = evalVal(r);
      return call('Input.dispatchPointerEvent', { eventType: 'pointermove', x: startPos.x, y: item0Y, pressed: true, pointerType: 'mouse', pointerId: 1 });
    }).then(() => sleep(100)).then(() => {
      return call('Runtime.evaluate', {
        expression: `(() => { const ul = document.querySelector('#draggable-list1'); return Array.from(ul.children).map((el, i) => i + ':' + el.textContent.replace(/<[^>]*>/g, '').trim()); })()`,
        returnByValue: true
      }).then(r => { console.log('[11] order after move to item0 region:', JSON.stringify(evalVal(r))); });
    }).then(() => {
      console.log('[12] pointerup');
      return call('Input.dispatchPointerEvent', { eventType: 'pointerup', x: startPos.x, y: evalVal2(startPos.x), pressed: false, pointerType: 'mouse', pointerId: 1, button: 'Left' }).catch(e => { console.log('[12b] pointerup err', e.message); return sleep(50); });
    }).then(() => sleep(150)).then(() => {
      return Promise.all([
        call('Runtime.evaluate', { expression: '!!window.__discDrag.state()', returnByValue: true }).then(r => { const a = evalVal(r); console.log('[13] after pointerup: drag ACTIVE=' + a); return a; }),
        call('Runtime.evaluate', {
          expression: `(() => { const ul = document.querySelector('#draggable-list1'); return Array.from(ul.children).map((el, i) => i + ':' + el.textContent.replace(/<[^>]*>/g, '').trim()); })()`,
          returnByValue: true
        }).then(r => { console.log('[14] FINAL order:', JSON.stringify(evalVal(r))); return evalVal(r); })
      ]);
    }).then((results) => {
      const final = results[1];
      const dragText = 'Волевой';
      const moved = final && final[0].split(':')[1] === dragText;
      console.log('[15] did Волевой move to index0? ' + String(moved));
      if (moved) { console.log('[16] PASS'); kill(); } else { console.log('[16] FAIL (not moved)'); kill(); }
    });
  }).catch(e => { console.log('ERR ' + e.message); kill(); });
}
