          if(evalVal(r)!==true){ console.log('FAIL modal not open'); kill(2); }
          console.log('[4] modal open');
        });
      });
  });
  // geometry
  steps.push(geomProbe('[5] item2', 2));
  // pointerdown
  steps.push(s => {
    const startPos = steps[steps.length-2];
    console.log('[6] pointerdown at (' + startPos.x + ',' + startPos.y + ')');
    return ptr('pointerdown', startPos.x, startPos.y, true).then(()=>sleep(100));
