  });
  steps.push(() => Promise.all([stateProbe('[12] after pointerup'), orderProbe('[13] FINAL order')]));

  return Promise.all(steps).then(() => {
    const final = steps[steps.length-1][1];
    const dragText = 'Волевой';
    const moved = final && final[0].split(':')[1] === dragText;
    console.log('[14] did Волевой move to index0? ' + String(moved));
    if (moved) { console.log('[15] PASS'); kill(0); } else { console.log('[15] FAIL (not moved)'); kill(1); });
